// TreeNode 由评测环境提供
class Solution {
    // 思路:前序首元素为根,中序定位后递归建树
    // 关键:idx 哈希表加速中序定位;pos 为前序取根指针
    // 易错:pos 与 idx 需在每次调用前重置
    // 复杂度:时间 O(n),空间 O(n)
public:
    int pos = 0;
    unordered_map<int, int> idx;

    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        pos = 0;
        idx.clear();
        for (int i = 0; i < (int)inorder.size(); i++) idx[inorder[i]] = i;
        return build(preorder, 0, (int)inorder.size() - 1);
    }

    TreeNode* build(vector<int>& preorder, int l, int r) {
        if (l > r) return nullptr;
        int val = preorder[pos++];
        TreeNode* node = new TreeNode(val);
        int m = idx[val];  // 中序定位根,切分左右子树
        node->left = build(preorder, l, m - 1);
        node->right = build(preorder, m + 1, r);
        return node;
    }
};

