class Solution {
    // 思路:后序遍历,统计经过每个节点的最大路径和
    // 关键:左右子树贡献先与 0 取大,再更新全局答案
    // 易错:ans 初始化为 INT_MIN,防止全负节点
    // 复杂度:时间 O(n),空间 O(h),h 为树高
public:
    int maxPathSum(TreeNode* root) {
        ans = INT_MIN;
        dfs(root);
        return ans;
    }
    int dfs(TreeNode* node) {
        if (!node) return 0;
        int l = max(0, dfs(node->left));
        int r = max(0, dfs(node->right));
        ans = max(ans, l + r + node->val);  // 更新经过当前节点的最大路径和
        return max(l, r) + node->val;
    }
private:
    int ans;
};

