class Solution {
    // 思路:BFS 层序遍历,收集每层最后一个节点
    // 关键:记录每层节点数 sz,弹出到最后一个时记录值
    // 易错:空树直接返回空结果
    // 复杂度:时间 O(n),空间 O(n)
public:
    vector<int> rightSideView(TreeNode* root) {
        vector<int> out;
        if (!root) return out;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int sz = (int)q.size();
            for (int i = 0; i < sz; i++) {
                TreeNode* cur = q.front(); q.pop();
                if (i == sz - 1) out.push_back(cur->val);  // 本层最后一个节点即右视图节点
                if (cur->left) q.push(cur->left);
                if (cur->right) q.push(cur->right);
            }
        }
        return out;
    }
};

