// TreeNode 由评测环境提供
class Solution {
    // 思路:前缀和哈希,统计根到当前节点的路径中和为 target 的数量
    // 关键:pre 记录前缀和出现次数,累加 pre[cur - target]
    // 易错:回溯时 pre[cur] 自减;用 long long 防溢出
    // 复杂度:时间 O(n),空间 O(h),h 为树高
public:
    int pathSum(TreeNode* root, int targetSum) {
        unordered_map<long long, int> pre;
        pre[0] = 1;
        int ans = 0;
        function<void(TreeNode*, long long)> dfs = [&](TreeNode* node, long long cur) {
            if (!node) return;
            cur += node->val;
            ans += pre[cur - targetSum];  // 累加以当前节点为终点的合法路径数
            pre[cur]++;
            dfs(node->left, cur);
            dfs(node->right, cur);
            pre[cur]--;
        };
        dfs(root, 0);
        return ans;
    }
};

